exec(open('build.py').read().split('def subs')[1].join(['def subs','']) if False else '')
def subs(i):
    a=m.GetAtomWithIdx(i); d={}
    ri=m.GetRingInfo()
    for n in a.GetNeighbors():
        if n.GetSymbol()=='O': d['O']=n.GetIdx()
        elif not n.GetIsAromatic(): d['CF3']=n.GetIdx()
        else:
            ring=[r for r in ri.AtomRings() if n.GetIdx() in r and len(r)==6][0]
            sub=sum(1 for j in ring for nb in m.GetAtomWithIdx(j).GetNeighbors() if nb.GetIdx() not in ring and nb.GetSymbol()!='H')
            d['Ph' if sub==1 else 'Ar']=n.GetIdx()
    return d
def vol(P,c,d):
    v=[P[d[k]]-P[c] for k in ('O','Ph','CF3')]
    return np.sign(np.dot(v[0],np.cross(v[1],v[2])))
